import java.util.Stack;

class MinStack {
    private Stack<Integer> stack;     // 主堆疊
    private Stack<Integer> minStack;  // 最小值堆疊

    /**
     * 雙堆疊實現 Min Stack
     * 所有操作的時間複雜度: O(1)
     * 空間複雜度: O(n)
     */

    public MinStack() {
        stack = new Stack<>();
        minStack = new Stack<>();
    }

    public void push(int val) {
        // 推入主堆疊
        stack.push(val);

        // 如果最小值堆疊為空，或新值 ≤ 當前最小值
        if (minStack.isEmpty() || val <= minStack.peek()) {
            minStack.push(val);
        }
    }

    public void pop() {
        if (!stack.isEmpty()) {
            // 注意：使用 equals 比較 Integer 物件
            if (stack.peek().equals(minStack.peek())) {
                minStack.pop();
            }
            stack.pop();
        }
    }

    public int top() {
        return stack.peek();
    }

    public int getMin() {
        return minStack.peek();
    }
}

